    );
  });

  const promises = [];
  for (const file of files) {
    // @example ./packages/babel-parser/src/index.js
    const dest = "./" + mapSrcToLib(file.slice(2));
    promises.push(worker.transform(file, dest));
  }
  return Promise.all(promises).finally(() => {
    if (worker.end !== undefined) {
      worker.end();
    }
  });
}

